"""The storage contract shared by every backend."""

import re
from typing import Protocol

from lifegather.database import ACTING_ACCOUNT

# Keys are generated by the application (never from file names) and stay
# portable across filesystems and S3-compatible services.
KEY_PATTERN = re.compile(r"[a-z0-9][a-z0-9_-]*(?:/[a-z0-9][a-z0-9_-]*){0,7}")
MAX_KEY_LENGTH = 512


class StorageError(Exception):
    """Storage failed; messages never include stored content or credentials."""


class ObjectNotFound(StorageError):
    pass


def validate_key(key: str) -> str:
    if len(key) > MAX_KEY_LENGTH or not KEY_PATTERN.fullmatch(key):
        raise StorageError("Invalid storage object key")
    account = ACTING_ACCOUNT.get()
    # Requests and jobs acting for an account reach only that account's files.
    if account is not None and not key.startswith(f"users/{account}/"):
        raise StorageError("Storage object belongs to another account")
    return key


class ObjectStorage(Protocol):
    def save(self, data: bytes, key: str) -> None:
        """Store bytes under key, replacing any previous object atomically."""

    def get(self, key: str) -> bytes:
        """Return stored bytes or raise ObjectNotFound."""

    def delete(self, key: str) -> None:
        """Remove the object; deleting a missing object is not an error."""

    def exists(self, key: str) -> bool: ...
